import React from "react";
import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type TankClimbProps = Record<string, any>;

// Helper to draw the M1 Abrams tank 2D profile
const TankProfile: React.FC<{ color: string; strokeWidth: number; fillColor: string }> = ({
  color,
  strokeWidth,
  fillColor,
}) => {
  const trackColor = "#2a2a2a";
  const wheelColor = "#111111";

  return (
    <g stroke={color} strokeWidth={strokeWidth} fill="none" strokeLinecap="round" strokeLinejoin="round">
      {/* Track Outline */}
      <path fill={trackColor} d="M 20 -30 L 225 -30 A 15 15 0 0 1 225 0 L 20 0 A 15 15 0 0 1 20 -30 Z" />
      
      {/* Wheels (Drive sprocket, 7 Road wheels, Idler) */}
      <circle fill={wheelColor} cx="20" cy="-15" r="10" />
      <circle fill={wheelColor} cx="45" cy="-15" r="10" />
      <circle fill={wheelColor} cx="70" cy="-15" r="10" />
      <circle fill={wheelColor} cx="95" cy="-15" r="10" />
      <circle fill={wheelColor} cx="120" cy="-15" r="10" />
      <circle fill={wheelColor} cx="145" cy="-15" r="10" />
      <circle fill={wheelColor} cx="170" cy="-15" r="10" />
      <circle fill={wheelColor} cx="195" cy="-15" r="10" />
      <circle fill={wheelColor} cx="225" cy="-15" r="9" />
      
      {/* Hull / Chassis */}
      <path fill={fillColor} d="M 5 -35 L 5 -55 L 80 -55 L 85 -60 L 200 -60 L 245 -40 L 240 -35 Z" />
      
      {/* Side Skirts */}
      <path fill={fillColor} d="M 5 -35 L 240 -35 L 235 -15 L 15 -15 Z" />
      
      {/* Skirt Panel Lines */}
      <line x1="45" y1="-35" x2="45" y2="-15" />
      <line x1="80" y1="-35" x2="80" y2="-15" />
      <line x1="115" y1="-35" x2="115" y2="-15" />
      <line x1="150" y1="-35" x2="150" y2="-15" />
      <line x1="185" y1="-35" x2="185" y2="-15" />
      <line x1="220" y1="-35" x2="220" y2="-15" />
      
      {/* Turret Profile */}
      <path fill={fillColor} d="M 70 -60 L 35 -60 L 35 -75 L 75 -85 L 140 -85 L 175 -60 Z" />
      
      {/* Turret Side Angles */}
      <line x1="75" y1="-85" x2="70" y2="-60" />
      <line x1="140" y1="-85" x2="145" y2="-60" />
      
      {/* Main Gun (120mm Smoothbore) */}
      <line x1="175" y1="-75" x2="350" y2="-75" strokeWidth={strokeWidth + 2} />
      
      {/* Mantlet Base */}
      <path fill={fillColor} d="M 165 -85 L 185 -80 L 185 -70 L 165 -65 Z" />
      
      {/* Bore Evacuator */}
      <rect fill={fillColor} x="250" y="-79" width="40" height="8" rx="2" />
      
      {/* Muzzle Reference System */}
      <rect fill={fillColor} x="345" y="-79" width="5" height="4" />
      
      {/* Antennas */}
      <line x1="45" y1="-75" x2="35" y2="-130" />
      <line x1="60" y1="-75" x2="55" y2="-140" />
      
      {/* CITV (Commander's Viewer) */}
      <rect fill={fillColor} x="110" y="-95" width="12" height="10" />
      <line x1="116" y1="-95" x2="116" y2="-100" />
      
      {/* CROWS / Machine Gun detail */}
      <path d="M 85 -85 L 85 -92 L 100 -92 L 105 -95" />
    </g>
  );
};

const TankClimb: React.FC<TankClimbProps> = ({
  backgroundColor = "#080c16",
  transparentBackground = true,
  durationInSeconds = 12, // Increased default duration to accommodate the slower drive
  lineColor = "#ffffff",
  tankColor = "#4b5320",
  maxAngle = 60,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const introDuration = 20;
  const angleAnimationStart = introDuration;
  const angleAnimationDuration = 25; // Decreased from 45 to make the angle line animation faster
  const tankDriveStart = angleAnimationStart + angleAnimationDuration + 10;
  const tankDriveDuration = 240; // Doubled from 120 to make the tank move significantly slower

  // Layout points
  const pivotX = width * 0.15;
  const pivotY = height * 0.8;
  const groundStartX = width * 0.05;

  // Calculate dynamic line length to prevent cutting off at top
  const maxAngleRadForCalc = (maxAngle * Math.PI) / 180;
  const verticalClearance = height * 0.20; 
  const availableHeight = pivotY - verticalClearance;
  const maxSafeLineLength = availableHeight / Math.max(Math.sin(maxAngleRadForCalc), 0.01);
  
  const preferredLineLength = width * 0.75; 
  const lineLength = Math.min(preferredLineLength, maxSafeLineLength);
  
  const groundEndX = pivotX + lineLength; 
  const arcRadius = width * 0.12;

  // Animations
  const groundOpacity = interpolate(frame, [0, introDuration], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const angleProgress = interpolate(
    frame,
    [angleAnimationStart, angleAnimationStart + angleAnimationDuration],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.sin), 
    }
  );

  const currentAngle = interpolate(angleProgress, [0, 1], [0, maxAngle]);
  const currentAngleRad = (currentAngle * Math.PI) / 180;

  // Tank animations
  const tankAppearOpacity = interpolate(
    frame,
    [tankDriveStart - 15, tankDriveStart],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const driveProgress = interpolate(
    frame,
    [tankDriveStart, tankDriveStart + tankDriveDuration],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.sin),
    }
  );

  // Dynamic max drive distance ensures the tank's front tracks never leave the end of the line
  const trackLength = 205 * 1.5; 
  const maxPossibleDrive = Math.max(0, lineLength - trackLength);
  const maxDriveDistance = Math.min(lineLength * 0.55, maxPossibleDrive);
  
  const currentDriveDistance = interpolate(driveProgress, [0, 1], [0, maxDriveDistance]);

  // Tank position calculation
  const tankX = pivotX + currentDriveDistance * Math.cos(currentAngleRad);
  const tankY = pivotY - currentDriveDistance * Math.sin(currentAngleRad);

  // Incline end point
  const inclineEndX = pivotX + lineLength * Math.cos(currentAngleRad);
  const inclineEndY = pivotY - lineLength * Math.sin(currentAngleRad);

  // Arc path calculation
  const arcEndX = pivotX + arcRadius * Math.cos(currentAngleRad);
  const arcEndY = pivotY - arcRadius * Math.sin(currentAngleRad);
  const arcPath =
    currentAngle > 0.1
      ? `M ${pivotX + arcRadius} ${pivotY} A ${arcRadius} ${arcRadius} 0 0 0 ${arcEndX} ${arcEndY}`
      : "";

  const textOpacity = interpolate(frame, [angleAnimationStart + 10, angleAnimationStart + 30], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: robotoMonoFamily }}>
      <svg width={width} height={height} style={{ position: "absolute", inset: 0 }}>
        <g style={{ opacity: groundOpacity }}>
          {/* Ground Line */}
          <line
            x1={groundStartX}
            y1={pivotY}
            x2={pivotX}
            y2={pivotY}
            stroke={lineColor}
            strokeWidth={5}
            strokeDasharray="12, 12"
          />
          {/* Solid Ramp Base */}
          <line
            x1={pivotX}
            y1={pivotY}
            x2={groundEndX}
            y2={pivotY}
            stroke={lineColor}
            strokeWidth={5}
            strokeLinecap="round"
          />

          {/* Incline Line */}
          <line
            x1={pivotX}
            y1={pivotY}
            x2={inclineEndX}
            y2={inclineEndY}
            stroke={lineColor}
            strokeWidth={8}
            strokeLinecap="round"
          />

          {/* Pivot Point */}
          <circle cx={pivotX} cy={pivotY} r={10} fill={backgroundColor} stroke={lineColor} strokeWidth={5} />

          {/* Angle Arc */}
          {arcPath && (
            <path
              d={arcPath}
              fill="none"
              stroke={lineColor}
              strokeWidth={4}
              strokeDasharray="8, 8"
            />
          )}

          {/* Tank Profile */}
          <g
            style={{ opacity: tankAppearOpacity }}
            transform={`translate(${tankX}, ${tankY}) rotate(${-currentAngle}) scale(1.5)`}
          >
            {/* Offset slightly back so the back wheel sits on the pivot initially */}
            <g transform="translate(-20, 0)">
              <TankProfile color={lineColor} strokeWidth={3} fillColor={tankColor} />
            </g>
          </g>
        </g>
      </svg>

      {/* Angle Readout */}
      <div
        style={{
          position: "absolute",
          left: pivotX + arcRadius + 40,
          top: pivotY - arcRadius * 0.5 - 30,
          color: lineColor,
          fontSize: "64px",
          fontWeight: "bold",
          opacity: textOpacity,
          transform: `translateY(${interpolate(textOpacity, [0, 1], [20, 0])}px)`,
        }}
      >
        {maxAngle}°
      </div>
    </AbsoluteFill>
  );
};

export default TankClimb;